<?php
require_once __DIR__ . '/../config.php'; require_once __DIR__ . '/../php/proposal_revisions.php'; require_once __DIR__ . '/../php/submissions.php'; require_once __DIR__ . '/../php/email_notifications.php';
if (session_status() !== PHP_SESSION_ACTIVE) session_start();
if (empty($_SESSION['user']) || $_SESSION['user']['role'] !== 'evaluator') { header('Location: ../index.php'); exit; }
$evaluatorId=(int)$_SESSION['user']['id']; $cycleId=(int)($_GET['cycle_id']??0);
if (!proposal_revision_schema_available($pdo)) { http_response_code(503); exit('The proposal revision review schema is not installed. Apply sql/migrations/023_proposal_revision_panel_reviews.sql.'); }
$load=static function(PDO $pdo,int $cycleId,int $evaluatorId):?array { $stmt=$pdo->prepare("SELECT c.*,c.id revision_cycle_id,p.title,p.group_name,p.google_drive_url,p.github_url,p.other_project_url,s.original_filename,s.stored_filename,s.id submission_id,r.id revision_review_id,r.decision,r.comments,r.submitted_at FROM proposal_revision_cycles c INNER JOIN projects p ON p.id=c.project_id INNER JOIN student_submissions s ON s.id=c.revision_submission_id INNER JOIN proposal_revision_reviews r ON r.revision_cycle_id=c.id WHERE c.id=? AND r.evaluator_id=? LIMIT 1"); $stmt->execute([$cycleId,$evaluatorId]); return $stmt->fetch(PDO::FETCH_ASSOC)?:null; };
$cycle=$load($pdo,$cycleId,$evaluatorId); if(!$cycle){http_response_code(403);exit('You are not assigned to this revision review.');}
$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!csrf_check($_POST['csrf']??'')) $errors[]='Your session could not be verified.';
 elseif($cycle['decision']!=='pending') $errors[]='This revision review is already finalized.';
 else { $decision=(string)($_POST['decision']??'');$comments=trim((string)($_POST['comments']??'')); if(!in_array($decision,['accepted','returned'],true)||$comments==='')$errors[]='Select a decision and provide feedback.';
  if(!$errors)try{$pdo->beginTransaction();
   // Serialize decisions for this cycle so the last two panel submissions
   // cannot each calculate the status against a different pending snapshot.
   $cycleLock=$pdo->prepare('SELECT id FROM proposal_revision_cycles WHERE id=? FOR UPDATE');
   $cycleLock->execute([(int)$cycle['revision_cycle_id']]);
   if(!$cycleLock->fetchColumn()) throw new RuntimeException('This revision cycle is no longer available.');
   $lock=$pdo->prepare('SELECT id FROM proposal_revision_reviews WHERE id=? AND revision_cycle_id=? AND evaluator_id=? FOR UPDATE');
   $lock->execute([(int)$cycle['revision_review_id'],(int)$cycle['revision_cycle_id'],$evaluatorId]);
   if(!$lock->fetchColumn()) throw new RuntimeException('This review is no longer available.');
   // c.id identifies a cycle; r.id identifies the evaluator review to update.
   $update=$pdo->prepare("UPDATE proposal_revision_reviews SET decision=?,comments=?,submitted_at=NOW() WHERE id=? AND revision_cycle_id=? AND evaluator_id=? AND decision='pending'");
   $update->execute([$decision,$comments,(int)$cycle['revision_review_id'],(int)$cycle['revision_cycle_id'],$evaluatorId]); if($update->rowCount()!==1)throw new RuntimeException('This review was already submitted.');
   $summary=proposal_revision_refresh_status($pdo,(int)$cycle['revision_cycle_id']);
   if($summary['status']==='accepted'){$pdo->prepare('UPDATE projects SET proposal_revision_accepted_submission_id=? WHERE id=?')->execute([(int)$cycle['revision_submission_id'],(int)$cycle['project_id']]);$pdo->prepare("UPDATE student_submissions SET status='accepted' WHERE id=?")->execute([(int)$cycle['revision_submission_id']]);}
   elseif($summary['status']==='returned')$pdo->prepare("UPDATE student_submissions SET status='revision_required' WHERE id=?")->execute([(int)$cycle['revision_submission_id']]);
   $pdo->commit();
   if($summary['pending_count']===0){
    $student=$pdo->prepare('SELECT u.id FROM projects p INNER JOIN users u ON u.id=p.student_id WHERE p.id=?');
    $student->execute([(int)$cycle['project_id']]);
    if($studentId=$student->fetchColumn())notify_user_once($pdo,(int)$studentId,'proposal-revision-complete:'.$cycleId,'Proposal revision panel review complete',$summary['status']==='accepted'?'Every original panel evaluator accepted your revised proposal. The Proposal Stage is complete and Final Defense submission is now available.':'Your revised proposal was returned with additional panel feedback.','students/student_dashboard.php?view=proposal');
    if($summary['status']==='accepted'){
     foreach($pdo->query("SELECT id FROM users WHERE role='dean'")->fetchAll(PDO::FETCH_COLUMN) as $chairId){
      notify_user_once($pdo,(int)$chairId,'proposal-revision-panel-accepted:'.$cycleId.':'.$chairId,'Proposal revision accepted','All original panel evaluators accepted a revised proposal. The student can now submit the Final Defense package.','dean/submissions.php');
     }
    }
   }
   header('Location: review_proposal_revision.php?cycle_id='.$cycleId);exit;
  }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='The review could not be saved. Please try again.';error_log('[proposal revision] '.$e->getMessage());}}
}
// Load persisted state after a post/redirect/get, never the stale pre-update row.
$cycle=$load($pdo,$cycleId,$evaluatorId)?:$cycle;$summary=proposal_revision_review_summary($pdo,(int)$cycle['revision_cycle_id']);
$original=$pdo->prepare("SELECT pe.*,u.full_name FROM proposal_evaluations pe INNER JOIN users u ON u.id=pe.evaluator_id WHERE pe.project_id=? AND pe.proposal_submission_id=? AND pe.status='submitted' ORDER BY u.full_name");$original->execute([(int)$cycle['project_id'],(int)$cycle['original_submission_id']]);$originalReviews=$original->fetchAll(PDO::FETCH_ASSOC);
$displayName=trim((string)($_SESSION['user']['full_name']??'Evaluator'))?:'Evaluator';$displayEmail=trim((string)($_SESSION['user']['email']??''))?:'No email available';$statusLabel=match($cycle['status']){'accepted'=>'Revision Accepted','returned'=>'Returned for Further Corrections',default=>'Pending Panel Review'};
function revision_sidebar(string $name,string $email):void{?><aside class="sidebar evaluator-sidebar" id="evaluator-sidebar" aria-label="Evaluator navigation"><div class="sidebar-header"><img class="logo-icon" src="../images_bgnd/CSUCC%20LOGO.png" alt="" aria-hidden="true"><div class="brand-copy"><span class="brand-line">CAPSTONE</span><span class="brand-line brand-emphasis">EVALUATION SYSTEM</span><small>EVALUATOR PORTAL</small></div></div><ul class="sidebar-nav"><li class="nav-section-label">Workspace</li><li><a href="dashboard.php"><span class="nav-icon" aria-hidden="true">▦</span><span class="nav-label">Dashboard</span></a></li><li class="nav-section-label">Evaluation</li><li><a class="active" aria-current="page" href="projects.php"><span class="nav-icon" aria-hidden="true">▰</span><span class="nav-label">Evaluation Workspace</span></a></li><li><a href="evaluation_history.php"><span class="nav-icon" aria-hidden="true">◷</span><span class="nav-label">Evaluation History</span></a></li><li class="nav-section-label">Account</li><li><a href="profile.php"><span class="nav-icon" aria-hidden="true">◎</span><span class="nav-label">Profile</span></a></li><li><a href="../logout.php"><span class="nav-icon" aria-hidden="true">↪</span><span class="nav-label">Logout</span></a></li></ul><div class="sidebar-user evaluator-sidebar-user"><div class="sidebar-user-avatar" aria-hidden="true"><?=esc(strtoupper(substr($name,0,1)))?></div><div class="sidebar-user-info"><h5><?=esc($name)?></h5><p><?=esc($email)?></p></div></div></aside><?php }
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Review Revised Proposal</title><link rel="stylesheet" href="../assets/style.css?v=20260918"><link rel="stylesheet" href="evaluator-content.css?v=20261106"><link rel="stylesheet" href="evaluator-typography.css?v=20261112"><link rel="stylesheet" href="revision-review.css?v=20261126"></head><body class="evaluator-content-page"><div class="dashboard-layout evaluator-layout"><?php revision_sidebar($displayName,$displayEmail);?><button class="sidebar-backdrop" type="button" aria-label="Close navigation" tabindex="-1"></button><main class="main-content revision-review-page"><div class="evaluator-topbar"><button class="mobile-menu-toggle" type="button" aria-label="Open navigation menu" aria-controls="evaluator-sidebar" aria-expanded="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><div class="evaluator-topbar-end"><div class="account-avatar" aria-hidden="true"><?=esc(strtoupper(substr($displayName,0,1)))?></div><span><?=esc($displayName)?></span></div></div><a class="selection-back" href="projects.php">← Evaluation Workspace</a><header class="main-header revision-header"><div class="main-header-text"><span class="page-eyebrow">Proposal revision <?=esc((string)$cycle['revision_number'])?></span><h1>Review Revised Proposal</h1><p><?=esc($cycle['title'])?><?=!empty($cycle['group_name'])?' · '.esc($cycle['group_name']):''?></p></div><span class="status-pill status-<?=esc($cycle['status']==='accepted'?'completed':($cycle['status']==='returned'?'assigned':'pending'))?>"><?=esc($statusLabel)?></span></header><?php if($errors):?><div class="e3-alert error" role="alert"><?=esc(implode(' ',$errors))?></div><?php endif;?>
<section class="work-panel revision-panel"><div class="work-panel-head"><div><span class="evaluation-step">Revision <?=esc((string)$cycle['revision_number'])?></span><h2>Revised submission</h2><p>Review the replacement proposal and linked resources before recording your decision.</p></div><div class="revision-progress"><strong><?=esc((string)$summary['accepted_count'])?></strong> accepted · <strong><?=esc((string)$summary['pending_count'])?></strong> pending · <strong><?=esc((string)$summary['returned_count'])?></strong> returned</div></div><div class="revision-meta"><div class="revision-file"><span class="revision-file-mark">PDF</span><div><strong><?=esc($cycle['original_filename'])?></strong><span>Submitted <?=esc(date('M j, Y g:i A',strtotime((string)$cycle['created_at'])))?></span></div></div><a class="action-link" target="_blank" rel="noopener" href="view_submission.php?id=<?=esc((string)$cycle['submission_id'])?>&amp;stage=proposal">View Revised PDF</a></div><?php $links=['google_drive_url'=>'Google Drive','github_url'=>'GitHub','other_project_url'=>'Other project resource'];$hasLinks=false;foreach($links as $field=>$label)$hasLinks=$hasLinks||!empty($cycle[$field]);if($hasLinks):?><div class="revision-resource-links"><?php foreach($links as $field=>$label):if(!empty($cycle[$field])):?><a target="_blank" rel="noopener" href="<?=esc($cycle[$field])?>"><strong><?=esc($label)?></strong><small><?=esc($cycle[$field])?></small></a><?php endif;endforeach;?></div><?php endif;?></section>
<section class="work-panel revision-panel"><div class="work-panel-head"><div><span class="evaluation-step">Reference</span><h2>Original panel feedback</h2><p>Compare the revision against the original panel comments and required corrections.</p></div></div><div class="revision-feedback-list"><?php if(!$originalReviews):?><p>No submitted original-panel feedback is available.</p><?php endif;foreach($originalReviews as $review):?><article class="revision-feedback-card"><h3><?=esc($review['full_name'])?></h3><?php foreach(['overall_comments'=>'Overall comments','recommendations'=>'Recommendations','required_revisions'=>'Required revisions'] as $field=>$label):if(trim((string)($review[$field]??''))!==''):?><p><strong><?=esc($label)?></strong><?=nl2br(esc((string)$review[$field]))?></p><?php endif;endforeach;?></article><?php endforeach;?></div></section>
<section class="work-panel revision-panel"><div class="work-panel-head"><div><span class="evaluation-step">Your panel decision</span><h2><?= $cycle['decision']==='pending'?'Record your decision':esc($statusLabel)?></h2><p><?= $cycle['decision']==='pending'?'A submitted decision is final for this review cycle.':'This decision is stored in the revision workflow.'?></p></div></div><?php if($cycle['decision']!=='pending'):?><div class="revision-final"><span class="status-pill status-<?=esc($cycle['decision']==='accepted'?'completed':'assigned')?>"><?=esc($cycle['decision']==='accepted'?'Revision Accepted':'Returned for Further Corrections')?></span><?php if($cycle['submitted_at']):?><p>Submitted <?=esc(date('M j, Y g:i A',strtotime((string)$cycle['submitted_at'])))?></p><?php endif;?><p><?=nl2br(esc((string)$cycle['comments']))?></p></div><?php else:?><form method="post" class="revision-decision"><input type="hidden" name="csrf" value="<?=esc(csrf_token())?>"><fieldset><legend>Decision</legend><label class="revision-choice"><input required type="radio" name="decision" value="accepted"><span><strong>Revision Accepted</strong><small>The proposal addresses the required corrections.</small></span></label><label class="revision-choice"><input required type="radio" name="decision" value="returned"><span><strong>Return for Further Corrections</strong><small>Additional changes are required before acceptance.</small></span></label></fieldset><label class="revision-comment" for="comments"><span>Comments / feedback</span><textarea id="comments" name="comments" required maxlength="2000" rows="6" placeholder="Explain the decision and any next steps for the student."></textarea><small>Required · up to 2,000 characters</small></label><div class="revision-actions"><button class="btn primary" type="submit">Submit Review</button><span>Your decision updates the student revision status immediately.</span></div></form><?php endif;?></section></main></div><script src="evaluator-content.js?v=20261106" defer></script></body></html>
